import React, { useState } from 'react';
import RepeatingCard from '../../components/RepeatingCard';
import PhotoUploadGrid from '../../components/PhotoUploadGrid';
import { ErrorAlert } from '../../components/EmptyState';
import { reelService, reelPhotoService, extractApiError } from '../../api/services';
import StepPeopleModels from './StepPeopleModels';
import StepLocations from './StepLocations';
import StepProps from './StepProps';

const REEL_PHOTO_CATEGORIES = [
  { value: 'STORYBOARD', label: 'Storyboard (9:16 frames)', aspect: 'portrait', hint: 'Drag & drop portrait frames, or click to browse' },
  { value: 'WARDROBE', label: 'Wardrobe reference', aspect: 'square', hint: 'Drag & drop wardrobe references, or click to browse' },
  { value: 'BACKGROUND', label: 'Background reference', aspect: 'square', hint: 'Drag & drop background references, or click to browse' },
];

function AssignmentChips({ label, pool, selectedIds, onToggle, emptyHint }) {
  if (pool.length === 0) {
    return (
      <div className="rr-wizfield">
        <label>{label}</label>
        <div style={{ fontSize: 12, color: 'rgba(0,0,0,.45)' }}>{emptyHint}</div>
      </div>
    );
  }
  return (
    <div className="rr-wizfield">
      <label>
        {label} — {selectedIds.length ? pool.filter((p) => selectedIds.includes(p.id)).map((p) => p.name).join(', ') : 'none'}
      </label>
      <div className="rr-wiz-chips">
        {pool.map((item) => (
          <span className="rr-wiz-chip" key={item.id}>
            <label>
              <input type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => onToggle(item.id)} />
              {item.name}
            </label>
          </span>
        ))}
      </div>
    </div>
  );
}

export default function StepReels({ plan, onChanged }) {
  const [error, setError] = useState('');
  const reels = plan?.reels || [];
  const modelPool = plan?.plan_models || [];
  const locationPool = plan?.plan_locations || [];
  const propPool = plan?.props || [];

  const run = async (fn, message) => {
    try {
      await fn();
      onChanged();
    } catch (err) {
      setError(extractApiError(err, message));
    }
  };

  const add = () =>
    run(
      () => reelService.create({ shoot_plan: plan.id, title: `Reel ${reels.length + 1}`, order: reels.length }),
      'Could not add reel.'
    );
  const patch = (id, payload) => run(() => reelService.patch(id, payload), 'Could not save changes.');
  const remove = (id) => run(() => reelService.remove(id), 'Could not remove reel.');
  const move = (id, dir) => {
    const idx = reels.findIndex((r) => r.id === id);
    const swapWith = reels[idx + dir];
    if (!swapWith) return;
    run(
      () =>
        Promise.all([
          reelService.patch(id, { order: swapWith.order }),
          reelService.patch(swapWith.id, { order: reels[idx].order }),
        ]),
      'Could not reorder.'
    );
  };
  const duplicate = (r) =>
    run(
      () =>
        reelService.create({
          shoot_plan: plan.id,
          title: `${r.title} (copy)`,
          concept: r.concept,
          reference_link: r.reference_link,
          notes: r.notes,
          photographer_notes: r.photographer_notes,
          platform: r.platform,
          duration_seconds: r.duration_seconds,
          order: reels.length,
        }),
      'Could not duplicate.'
    );

  const toggleAssignment = (reel, field, id) => {
    const current = reel[field] || [];
    const next = current.includes(id) ? current.filter((x) => x !== id) : [...current, id];
    patch(reel.id, { [field]: next });
  };

  return (
    <>
      <div className="rr-wiz-step-title">Reels</div>
      <ErrorAlert message={error} />

      <div style={{ marginBottom: 28 }}>
        <StepPeopleModels plan={plan} onChanged={onChanged} />
      </div>
      <div style={{ marginBottom: 28, borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 24 }}>
        <StepLocations plan={plan} onChanged={onChanged} />
      </div>
      <div style={{ marginBottom: 28, borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 24 }}>
        <StepProps plan={plan} onChanged={onChanged} />
      </div>
      <div style={{ borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 24 }} />

      <div className="rr-stepbar">
        <span className="rr-stepbar__count">{reels.length} reel(s) briefed</span>
        <button type="button" className="rr-toggle-btn rr-toggle-btn--active" onClick={add}>
          + Add Reel
        </button>
      </div>

      {reels.length === 0 && (
        <div className="rr-wiz-empty">
          <div className="rr-wiz-empty__title">No reels briefed yet</div>
          <div className="rr-wiz-empty__text">Outline each reel's script and references.</div>
          <button type="button" className="rr-toggle-btn rr-toggle-btn--active" onClick={add}>
            + Add Reel
          </button>
        </div>
      )}

      {reels.map((r, idx) => (
        <RepeatingCard
          key={r.id}
          title={`Reel ${idx + 1}${r.title ? ` — ${r.title}` : ''}`}
          complete={!!(r.title && r.concept)}
          summary={`${r.title || 'Untitled'} · ${r.status_display}`}
          isFirst={idx === 0}
          isLast={idx === reels.length - 1}
          onMoveUp={() => move(r.id, -1)}
          onMoveDown={() => move(r.id, 1)}
          onDuplicate={() => duplicate(r)}
          onRemove={() => remove(r.id)}
        >
          <div className="rr-wizfield">
            <label>
              Reel title <span className="rr-wiz-required">*</span>
            </label>
            <input defaultValue={r.title} onBlur={(e) => patch(r.id, { title: e.target.value })} placeholder="e.g. Rooftop Sunset Walk" />
          </div>
          <div className="rr-wizfield">
            <label>
              Script <span className="rr-wiz-required">*</span>
            </label>
            <textarea rows={4} defaultValue={r.concept} onBlur={(e) => patch(r.id, { concept: e.target.value })} placeholder="Full script — paragraph breaks supported…" />
          </div>
          <div className="rr-wizfield">
            <label>Reference link</label>
            <input defaultValue={r.reference_link} onBlur={(e) => patch(r.id, { reference_link: e.target.value })} placeholder="Link to moodboard, reference reel…" />
          </div>
          <div className="rr-wizfield">
            <label>Notes to editor</label>
            <textarea rows={2} defaultValue={r.notes} onBlur={(e) => patch(r.id, { notes: e.target.value })} placeholder="Music, pacing, transitions…" />
          </div>
          <div className="rr-wizfield">
            <label>Photographer/Videographer notes</label>
            <textarea
              rows={3}
              defaultValue={r.photographer_notes}
              onBlur={(e) => patch(r.id, { photographer_notes: e.target.value })}
              placeholder="Camera movement, lens, frame rate, lighting, audio, special equipment…"
            />
          </div>

          {REEL_PHOTO_CATEGORIES.map((cat) => (
            <PhotoUploadGrid
              key={cat.value}
              label={cat.label}
              aspect={cat.aspect}
              hint={cat.hint}
              photos={(r.photos || []).filter((p) => p.category === cat.value)}
              onUpload={(file) => run(() => reelPhotoService.upload(r.id, file, { category: cat.value }), 'Upload failed.')}
              onRemove={(photoId) => run(() => reelPhotoService.remove(photoId), 'Could not remove photo.')}
            />
          ))}

          <div style={{ borderTop: '1px solid rgba(0,0,0,.08)', paddingTop: 14, marginTop: 4 }}>
            <AssignmentChips
              label="Models"
              pool={modelPool}
              selectedIds={r.assigned_models || []}
              onToggle={(id) => toggleAssignment(r, 'assigned_models', id)}
              emptyHint="Add models above first."
            />
            <AssignmentChips
              label="Locations"
              pool={locationPool}
              selectedIds={r.assigned_locations || []}
              onToggle={(id) => toggleAssignment(r, 'assigned_locations', id)}
              emptyHint="Add locations above first."
            />
            <AssignmentChips
              label="Props"
              pool={propPool}
              selectedIds={r.assigned_props || []}
              onToggle={(id) => toggleAssignment(r, 'assigned_props', id)}
              emptyHint="Add props in the Props step first."
            />
          </div>
        </RepeatingCard>
      ))}
    </>
  );
}
